import path from "path";
import fs from "fs/promises";
import { getAppDataPath } from "./sync.js";
import { existsSync, readdirSync } from "fs";
import { folderType } from "./types/base.type.js";

type Sectionkey = "notification" | "payment" | "onboarding";

function getBaseSectionKey(fileName: string): Sectionkey | null {
  if (fileName === "notification-base.json") return "notification";
  if (fileName === "payment-base.json") return "payment";
  if (fileName === "onboarding-base.json") return "onboarding";
  return null;
}

function baseCacheKey(folder: string): string {
  return `${folder}-base.json`;
}

function getFilePath(fileName: string): string {
  const baseDir = path.join(getAppDataPath(), "user-assets");

 

  const sectionKey = getBaseSectionKey(fileName);
  if (sectionKey) {
    return path.join(baseDir, "base.json");
  }

  let subFolder = "";
  if (fileName.startsWith("notification")) {
    subFolder = "notification";
  } else if (fileName.startsWith("payment")) {
    subFolder = "payment";
  } else if (fileName.startsWith("onboarding")) {
    subFolder = "onboarding";
  }

  if (subFolder) {
    return path.join(baseDir, subFolder, fileName);
  }

  return path.join(baseDir, fileName);
}

function hasFolderCache(folder: folderType): boolean {
  const dir = path.join(getAppDataPath(), "user-assets", folder);
  return existsSync(dir) && readdirSync(dir).length > 0;
}


async function loadCacheJson(fileName: string) {
  try {
    const filePath = getFilePath(fileName);
    const raw = await fs.readFile(filePath, "utf-8");
    const parsed = JSON.parse(raw);

    const sectionKey = getBaseSectionKey(fileName);
    if (sectionKey) {
      // Pull just this caller's slice out of the shared base.json.
      return parsed[sectionKey] ?? null;
    }
    return parsed;
  } catch (error) {
    return null;
  }
}

async function saveCacheJson<T>(fileName: string, data: T) {
  const filePath = getFilePath(fileName);
  const dir = path.dirname(filePath);

  await fs.mkdir(dir, { recursive: true });

  const sectionKey = getBaseSectionKey(fileName);

  if (sectionKey) {
    // notification-base.json / payment-base.json / onboarding-base.json
    // all share the same base.json file on disk, so we read whatever
    // is already there first and only update our own section -
    // otherwise saving one would wipe out the other two.
    let existing: Partial<Record<Sectionkey, unknown>> = {};
    try {
      const raw = await fs.readFile(filePath, "utf-8");
      existing = JSON.parse(raw);
    } catch (err) {
      // File doesn't exist yet, or is empty/corrupt - start fresh.
      existing = {};
    }

    existing[sectionKey] = data;

    await fs.writeFile(filePath, JSON.stringify(existing, null, 2), "utf-8");
    return;
  }

  // Normal, non-base file - just write it out directly.
  await fs.writeFile(filePath, JSON.stringify(data, null, 2), "utf-8");
}

export {
  getFilePath,
  saveCacheJson,
  baseCacheKey,
  getBaseSectionKey,
  loadCacheJson,
  hasFolderCache
};
